#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int MAXN = 5500;
const ll INF = 1e9 + 7;

struct Edge {
    int to;
    int cost;
    int back;
    int cap;
};

int n, m, k, c, d;
int u, v, mx, s = MAXN - 2, t = MAXN - 1, mf = 0;
int tr[MAXN];
ll ans = 0, dis[MAXN];
vector<Edge> g[MAXN];
priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;

inline void add_edge(int u, int v, int cost, int cap) {
    int iu = g[u].size();
    int iv = g[v].size();
    g[u].push_back({v, cost, iv, cap});
    g[v].push_back({u, -cost, iu, 0});
}

void dijkstra() {
    fill(dis, dis + MAXN, INF);
    pq.push({dis[s] = 0, s});
    while (!pq.empty()) {
        auto [du, x] = pq.top();
        pq.pop();
        if (du > dis[x]) continue;
        for (const Edge &e : g[x]) {
            if (e.cap > 0 && dis[e.to] > du + e.cost) {
                tr[e.to] = e.back;
                pq.push({dis[e.to] = du + e.cost, e.to});
            }
        }
    }
}

void trace() {
    int delta = k, v = t;
    while (v != s) {
        const Edge &rev = g[v][tr[v]];
        int u = rev.to;
        int fwd = rev.back;
        delta = min(delta, g[u][fwd].cap);
        v = u;
    }
    mf += delta;
    ans += delta * dis[t];
    v = t;
    while (v != s) {
        Edge &rev = g[v][tr[v]];
        int u = rev.to;
        int fwd = rev.back;
        rev.cap += delta;
        g[u][fwd].cap -= delta;
        v = u;
    }
}

int at(int u, int time) {
    return u + time * n;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> k >> c >> d;
    mx = n + k;
    for (int i = 0; i < k; i++) {
        cin >> u;
        add_edge(s, at(u, 0), 0, 1);
    }
    for (int i = 0; i <= mx; i++)
        add_edge(at(1, i), t, c * i, k);
    for (int i = 1; i <= n; i++)
        for (int j = 0; j < mx; j++)
            add_edge(at(i, j), at(i, j + 1), 0, k);
    while (m--) {
        cin >> u >> v;
        for (int i = 1; i <= k; i++)
            for (int j = 0; j < mx; j++) {
                add_edge(at(u, j), at(v, j + 1), d * (2 * i - 1), 1);
                add_edge(at(v, j), at(u, j + 1), d * (2 * i - 1), 1);
            }
    }
    while (mf < k) {
        dijkstra();
        trace();
    }
    cout << ans;
}
